def apply_rules(strings, rules):
    """Apply a sequence of rules to strings."""
    result = strings[:]
    for pattern, replacement in rules:
        result = [s.replace(pattern, replacement) for s in result]
    return result

def score_rules(inputs, outputs, rules):
    """Score how well rules match the expected outputs."""
    result = apply_rules(inputs, rules)
    correct = sum(1 for r, o in zip(result, outputs) if r == o)
    return correct / len(outputs)

def find_over_applications(inputs, outputs, rules):
    """Find examples where rules incorrectly modify strings."""
    result = apply_rules(inputs, rules)
    over_apps = []
    for i, (inp, outp, res) in enumerate(zip(inputs, outputs, result)):
        if res != outp and inp != outp:  # If result is wrong and input was different from output
            over_apps.append((i, inp, res))
    return over_apps

def simulate_rule_chain(s, rules):
    """Simulate applying rules step by step."""
    trace = []
    current = s
    for pattern, replacement in rules:
        prev = current
        current = current.replace(pattern, replacement)
        trace.append({
            'step': len(trace),
            'pattern': pattern,
            'replacement': replacement,
            'before': prev,
            'after': current
        })
    return trace

